  const snap=reports['stock-snapshot'];assert.equal(snap.count,2);assert.equal(snap.valuationBasis,'SELECTED_STORE_PURCHASE_HISTORY');assert.ok(snap.items.every(r=>r.costPrice===null));assert.equal(snap.items.find(r=>r.productId==='legacy15-product-zero').purchasePrice,0);const missing=snap.items.find(r=>r.productId==='legacy15-product-missing');assert.equal(missing.purchasePrice,null);assert.equal(missing.lastPurchaseAt,null);assert.equal(missing.supplierName,null);assert.equal(snap.totalCostValue,null);assert.equal(reports['item-snapshot'].count,2);
