  assert.equal((await get('/api/reports/delivery/legacy15-note-own/lines?storeId=selected')).status,200);assert.equal((await get('/api/reports/delivery/legacy15-note-sibling/lines?storeId=selected')).status,404);
  for(const family of ['stock-analysis/legacy15-product-unrelated/movements','sales-analysis/legacy15-product-unrelated'])assert.equal((await get('/api/reports/'+family+'?'+(family.startsWith('sales')?salesRange:range))).status,404);
  assert.equal((await get('/api/reports/stock-snapshot?to=2026-11-12&storeId=selected&q=L15_unrelated')).body.count,0);assert.equal((await get(paths.documents.replace('storeId=selected','storeId=sibling'))).status,403);assert.equal((await get(paths.documents,{companyHeader:'company'})).status,403);assert.equal((await get('/api/owner-products/stores')).status,403);assert.equal((await get('/api/reports/logins?'+range)).status,403);
  await mutate('UPDATE "StorePaidModule" SET "active"=false WHERE "id"=\'legacy15-paid-INVENTORY\'');for(const name of storeReportNames)assert.equal((await get(paths[name])).status,freeStoreReportCapabilities.includes('store-reports-'+name+'.read')?200:403);await mutate('UPDATE "StorePaidModule" SET "active"=true WHERE "id"=\'legacy15-paid-INVENTORY\'');
